agent_sql:
SELECT supplier_name
FROM gold.dim_supplier
WHERE country = 'United States';

SELECT COUNT(DISTINCT order_id) AS cancelled_orders_count
FROM gold.fact_orders
WHERE order_status = 'Cancelled';

SELECT COUNT(*) 
FROM gold.dim_customer 
WHERE segment = 'Enterprise' AND churn_status = 'Active';

SELECT COUNT(*) 
FROM gold.dim_customer 
WHERE segment = 'SMB' AND churn_status = 'At Risk';
